import {AlertPageHeader, AlertPageHeaderLink} from '@github-ui/platform-patterns/AlertPageHeader'
import type {AlertStatus} from '@github-ui/platform-patterns/AlertPageHeader'

import {TrailingMessage} from './TrailingMessage'
import type {TrailingMessageProps} from './TrailingMessage'

const STATUS_MAP: Record<string, AlertStatus> = {
  open: 'open',
  fixed: 'fixed',
  dismissed: 'dismissed',
}

export type DependabotAlertShowHeaderProps = {
  alertTitle: string
  alertNumber: number
  alertOpenedAt: string
  backButtonPath: string
  backButtonText?: string
  packageName: string
  ecosystem: string
  manifestPath: string
  manifestBlobPath: string
  state: string
} & TrailingMessageProps

export const DependabotAlertShowHeader = ({
  alertTitle,
  alertNumber,
  alertOpenedAt,
  backButtonPath,
  backButtonText = 'Dependabot alerts',
  packageName,
  ecosystem,
  manifestPath,
  manifestBlobPath,
  state,
  ...trailingMessageProps
}: DependabotAlertShowHeaderProps) => (
  <AlertPageHeader
    title={alertTitle}
    alertNumber={alertNumber}
    status={STATUS_MAP[state] ?? 'dismissed'}
    subtitle={
      <>
        On <span className="text-bold">{packageName}</span> ({ecosystem}){' '}
        <AlertPageHeaderLink href={manifestBlobPath}>{manifestPath}</AlertPageHeaderLink>
      </>
    }
    trailingMessage={hasTrailingMessage(trailingMessageProps) ? <TrailingMessage {...trailingMessageProps} /> : null}
    backButtonText={backButtonText}
    backButtonUrl={backButtonPath}
    timestamp={new Date(alertOpenedAt)}
  />
)

const hasTrailingMessage = ({showDismissMetadata, showAutoDismissMetadata, showFixedMetadata}: TrailingMessageProps) =>
  showDismissMetadata || showAutoDismissMetadata || showFixedMetadata
